SELECT COUNT(*) as cnt FROM Fires WHERE STATE='AK' AND date(
  substr(DISCOVERY_DATE, instr(DISCOVERY_DATE,'/', instr(DISCOVERY_DATE,'/')+1)+1) || '-' ||
  printf('%02d', substr(DISCOVERY_DATE,1, instr(DISCOVERY_DATE,'/')-1)) || '-' ||
  printf('%02d', substr(DISCOVERY_DATE, instr(DISCOVERY_DATE,'/')+1, instr(DISCOVERY_DATE, '/', instr(DISCOVERY_DATE,'/')+1)- instr(DISCOVERY_DATE,'/')-1))
) BETWEEN '1994-06-01' AND '1994-08-31';
